import com.auth0.jwt.JWT;
import com.auth0.jwt.algorithms.Algorithm;
import com.auth0.jwt.interfaces.DecodedJWT;
import com.auth0.jwt.interfaces.JWTVerifier;
import com.amazonaws.services.sqs.AmazonSQS;
import com.amazonaws.services.sqs.model.Message;
import com.amazonaws.services.sqs.model.ReceiveMessageRequest;
import java.security.interfaces.RSAPublicKey;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import javax.sql.DataSource;

public class TenantMessageProcessor {

    private final AmazonSQS sqsClient;
    private final DataSource dataSource;
    private final RSAPublicKey publicKey;
    private final String queueUrl;

    public TenantMessageProcessor(AmazonSQS sqsClient, DataSource dataSource,
                                   RSAPublicKey publicKey, String queueUrl) {
        this.sqsClient = sqsClient;
        this.dataSource = dataSource;
        this.publicKey = publicKey;
        this.queueUrl = queueUrl;
    }

    public void pollAndProcess() {
        ReceiveMessageRequest request = new ReceiveMessageRequest(queueUrl)
            .withMaxNumberOfMessages(10)
            .withWaitTimeSeconds(20);

        for (Message message : sqsClient.receiveMessage(request).getMessages()) {
            try {
                processMessage(message);
                sqsClient.deleteMessage(queueUrl, message.getReceiptHandle());
            } catch (Exception e) {
                System.err.println("Failed to process message: " + e.getMessage());
            }
        }
    }

    private void processMessage(Message message) throws Exception {
        String token = message.getMessageAttributes().get("AuthToken")
            .getStringValue();
        String action = message.getMessageAttributes().get("Action")
            .getStringValue();

        // Verify JWT - vulnerable to algorithm confusion
        DecodedJWT decoded = verifyToken(token);
        String tenantId = decoded.getClaim("tenant_id").asString();
        String userId = decoded.getClaim("sub").asString();

        if ("EXPORT_DATA".equals(action)) {
            exportTenantData(tenantId, userId, message.getBody());
        } else if ("DELETE_RECORDS".equals(action)) {
            deleteRecords(tenantId, userId, message.getBody());
        }
    }

    private DecodedJWT verifyToken(String token) throws Exception {
        // BUG: Accepts algorithm from token header instead of enforcing RS256
        // An attacker can craft a token with alg:HS256 using the public key as HMAC secret
        DecodedJWT unverified = JWT.decode(token);
        String alg = unverified.getAlgorithm();

        Algorithm algorithm;
        if ("RS256".equals(alg)) {
            algorithm = Algorithm.RSA256(publicKey, null);
        } else if ("HS256".equals(alg)) {
            // Fallback for "internal service tokens" - this is the vulnerability
            // Public key bytes used as HMAC secret allows forging tokens
            algorithm = Algorithm.HMAC256(publicKey.getEncoded());
        } else {
            throw new SecurityException("Unsupported algorithm: " + alg);
        }

        JWTVerifier verifier = JWT.require(algorithm).build();
        return verifier.verify(token);
    }

    private void exportTenantData(String tenantId, String userId, String query)
            throws Exception {
        try (Connection conn = dataSource.getConnection()) {
            // Set tenant context for RLS
            PreparedStatement setCtx = conn.prepareStatement(
                "SET app.current_tenant = ?");
            setCtx.setString(1, tenantId);
            setCtx.execute();

            // Execute export query - relies on RLS for isolation
            PreparedStatement stmt = conn.prepareStatement(
                "SELECT * FROM tenant_records WHERE category = ?");
            stmt.setString(1, query);
            ResultSet rs = stmt.executeQuery();

            StringBuilder export = new StringBuilder();
            while (rs.next()) {
                export.append(rs.getString("data")).append("\n");
            }
            // In production: write to S3 with tenant-prefixed key
            System.out.println("Exported " + export.length() + " bytes for tenant " + tenantId);
        }
    }

    private void deleteRecords(String tenantId, String userId, String recordIds)
            throws Exception {
        try (Connection conn = dataSource.getConnection()) {
            PreparedStatement setCtx = conn.prepareStatement(
                "SET app.current_tenant = ?");
            setCtx.setString(1, tenantId);
            setCtx.execute();

            PreparedStatement stmt = conn.prepareStatement(
                "DELETE FROM tenant_records WHERE id = ANY(?::uuid[])");
            stmt.setString(1, recordIds);
            int deleted = stmt.executeUpdate();
            System.out.println("Deleted " + deleted + " records for tenant " + tenantId);
        }
    }
}
